('table',[['Arquivo','Onde executar','Função'],['LabGuard-TI-Setup.exe','PC da TI','Filtro DNS completo, bancos, mapas, relatórios e acesso à Central.'],['LabGuard-Jogos.exe','Cada PC dos alunos','Proteção local automática: jogos reconhecidos e políticas dos navegadores.'],['LabGuardTecnico.exe','PC administrador','Central opcional: vínculos, avisos, políticas e Sites rápidos. Não é o filtro DNS.'],['LabGuard-TI-Portable.zip','PC da TI','Filtro em pasta: extraia tudo e abra LabGuard.exe.'],['LabGuard-Desinstalador.exe','PC a retirar do sistema','Remove componentes identificados e informa pendências. Não serve para atualizar.']]),
